import{_ as d,g as r,o,c as i,j as a,a as n,k as c,a2 as l}from"./chunks/framework.DXa1R37q.js";const s={class:"diagram-links"},v=["href"],b={class:"diagram-frame editorial"},p=["src"],_=JSON.parse('{"title":"Lifecycle and authority boundaries","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"learn/lifecycle.md","filePath":"learn/lifecycle.md","lastUpdated":1793122404000}'),h={name:"learn/lifecycle.md"},u=Object.assign(h,{setup(m){const t=r("/diagrams/neottia-lifecycle.html");return(f,e)=>(o(),i("div",null,[e[0]||(e[0]=a("h1",{id:"lifecycle-and-authority-boundaries",tabindex:"-1"},[n("Lifecycle and authority boundaries "),a("a",{class:"header-anchor",href:"#lifecycle-and-authority-boundaries","aria-label":'Permalink to "Lifecycle and authority boundaries"'},"​")],-1)),e[1]||(e[1]=a("p",null,"Neottia installs six public commands. Four advance delivery work. Two help recover context without silently advancing it.",-1)),a("div",s,[a("a",{href:c(t),target:"_blank",rel:"noreferrer"},"Open the interactive lifecycle in a new tab",8,v)]),a("div",b,[a("iframe",{src:c(t),title:"Interactive Neottia lifecycle and authority diagram",loading:"lazy"},null,8,p)]),e[2]||(e[2]=l('<h2 id="delivery-commands" tabindex="-1" data-v-94abc4c3>Delivery commands <a class="header-anchor" href="#delivery-commands" aria-label="Permalink to &quot;Delivery commands&quot;" data-v-94abc4c3>​</a></h2><table tabindex="0" data-v-94abc4c3><thead data-v-94abc4c3><tr data-v-94abc4c3><th data-v-94abc4c3>Command</th><th data-v-94abc4c3>Owns</th><th data-v-94abc4c3>Required stop</th></tr></thead><tbody data-v-94abc4c3><tr data-v-94abc4c3><td data-v-94abc4c3><code data-v-94abc4c3>/plan</code></td><td data-v-94abc4c3>Requirements, repository evidence, owning Epic, child work, and design scope</td><td data-v-94abc4c3>Stop for current scope or design approval</td></tr><tr data-v-94abc4c3><td data-v-94abc4c3><code data-v-94abc4c3>/build</code></td><td data-v-94abc4c3>Only the approved implementation scope</td><td data-v-94abc4c3>Stop with implementation evidence for Verify</td></tr><tr data-v-94abc4c3><td data-v-94abc4c3><code data-v-94abc4c3>/verify</code></td><td data-v-94abc4c3>Requirement coverage, checks, user-visible behavior, and verdict</td><td data-v-94abc4c3>Return defects to Build or present a current pass verdict</td></tr><tr data-v-94abc4c3><td data-v-94abc4c3><code data-v-94abc4c3>/release</code></td><td data-v-94abc4c3>Release metadata and one explicitly selected action</td><td data-v-94abc4c3>Stop before any action that lacks fresh authorization</td></tr></tbody></table><h2 id="recovery-commands" tabindex="-1" data-v-94abc4c3>Recovery commands <a class="header-anchor" href="#recovery-commands" aria-label="Permalink to &quot;Recovery commands&quot;" data-v-94abc4c3>​</a></h2><ul data-v-94abc4c3><li data-v-94abc4c3><code data-v-94abc4c3>/continue</code> reads durable records and recommends exactly one next public command. It does not invoke that command.</li><li data-v-94abc4c3><code data-v-94abc4c3>/refresh</code> reloads configuration, provider records, repository state, and source-control state. It reports drift without changing phase.</li></ul><h2 id="approval-rules" tabindex="-1" data-v-94abc4c3>Approval rules <a class="header-anchor" href="#approval-rules" aria-label="Permalink to &quot;Approval rules&quot;" data-v-94abc4c3>​</a></h2><p data-v-94abc4c3>Approval is narrow and current:</p><ul data-v-94abc4c3><li data-v-94abc4c3>Plan approval covers the recorded implementation scope.</li><li data-v-94abc4c3>It does not authorize merge, publication, deployment, remote closure, or destructive cleanup.</li><li data-v-94abc4c3>Release can prepare one action, but the action still needs explicit owner authorization.</li><li data-v-94abc4c3>A confirmed defect becomes one canonical Bug and returns through Build.</li><li data-v-94abc4c3>A stop records the exact revision, commits, checks, status, and recommended next command in an append-only checkpoint.</li></ul><p data-v-94abc4c3>These rules remain the same in Pi, OpenCode, and Claude Code. Adapters change host syntax and paths, not lifecycle authority.</p><p data-v-94abc4c3>Read the <a href="/projects/neottia/sdlc/protocol" data-v-94abc4c3>operating protocol reference</a> for the full checkpoint and ownership contract. See <a href="/projects/neottia/reference/diagrams" data-v-94abc4c3>diagram sources and attribution</a> for evidence and license details.</p>',9))]))}}),g=d(u,[["__scopeId","data-v-94abc4c3"]]);export{_ as __pageData,g as default};
